            qk_rms_ml_kernel<256, 0, false><<<(unsigned)(2 * nt), 256, 0, stream>>>(q, k, wq, wk, qo, ko, (int)nt, eps);
    } else {
        const long long nt = n_rows / 32;
        qk_rms_ml_kernel<512, 0, false><<<(unsigned)(2 * nt), 512, 0, stream>>>(q, k, wq, wk, qo, ko, (int)nt, eps);
    }
    return (int)cudaGetLastError();
}
